import request from './request'

// 认证相关 API：登录、注册、获取用户信息
export const authApi = {
  login: (data) => request.post('/auth/login', data),         // 登录
  register: (data) => request.post('/auth/register', data),   // 注册
  getUserInfo: () => request.get('/auth/userinfo'),           // 获取当前用户信息
  getUsers: () => request.get('/auth/users')                  // 获取所有用户列表（管理员）
}

// 维修记录相关 API：CRUD + 统计 + 图片上传
export const maintenanceApi = {
  getList: (params) => request.get('/maintenance/list', { params }),        // 获取列表（分页+筛选）
  getDetail: (id) => request.get(`/maintenance/detail/${id}`),              // 获取详情
  create: (data) => request.post('/maintenance/create', data),              // 新建报修
  update: (id, data) => request.put(`/maintenance/update/${id}`, data),     // 更新记录
  delete: (id) => request.delete(`/maintenance/delete/${id}`),              // 删除记录
  getByElement: (elementId) => request.get(`/maintenance/by-element/${elementId}`), // 按构件查关联记录
  getStatistics: () => request.get('/maintenance/statistics'),              // 获取统计数据
  // 上传图片：接收FormData对象，返回图片URL数组
  uploadImages: (formData) => request.post('/maintenance/upload', formData, {
    headers: { 'Content-Type': 'multipart/form-data' },
    timeout: 30000  // 上传超时时间30秒
  })
}

// BIMface 相关 API：获取token和模型列表
export const bimfaceApi = {
  getToken: () => request.get('/bimface/token'),              // 获取 Access Token
  getViewToken: (fileId) => request.get(`/bimface/view-token/${fileId}`),  // 获取模型 View Token
  getModels: () => request.get('/bimface/models')             // 获取模型列表（含viewToken）
}
